 @Test void independentlyArchivedClosedThreeStatementsNeedNoAiAndNeverFollowLaterSnapshotsOrGrantLedgerRights(){var report=closedReport();var extended=extended(null,null);var sources=new FinanceArchiveSources(named,access,null,null,accounting,null,insights,null);sources.setExtended(extended);var archives=new FinanceArchiveService(named,db,access,audit,sources);var source=call(()->extended.createReportSource(new FinanceArchiveExtendedSources.ReportSource(UUID.randomUUID(),book,"2026-10",report.get("reportVersion").toString())));UUID sourceId=id(source.get("sourceId"));var archived=call(()->archives.freeze(new FinanceArchiveModels.Freeze(UUID.randomUUID(),"BOOK_REPORT",sourceId,source.get("sourceVersion").toString(),"独立正式三表档案",true)));UUID archive=id(archived.get("id"));assertThat(map(archived.get("snapshot"))).containsEntry("sourceType","BOOK_REPORT");assertThat(rows(map(archived.get("snapshot")).get("graph"))).anySatisfy(r->assertThat(r).containsEntry("relation","EXACT_FROZEN_REPORT_VERSION"));var exported=call(()->archives.exportReport(archive,report.get("reportVersion").toString(),"INCOME_STATEMENT","xlsx"));assertThat(exported.reportVersion()).isEqualTo(report.get("reportVersion"));assertThat(exported.content()).startsWith((byte)'P',(byte)'K');assertThatThrownBy(()->call(()->archives.exportReport(archive,"not-this-frozen-version","INCOME_STATEMENT","xlsx"))).hasMessageContaining("版本");assertThat(jdbc.queryForObject("select count(*) from fi_report where tenant_id=?",Integer.class,T)).isZero();assertThatThrownBy(()->jdbc.update("update fac_report_source set payload='{}' where id=?",sourceId)).hasMessageContaining("append-only");as(reviewer,Set.of(hotel),"finance.archive.grant");assertThatThrownBy(()->call(()->archives.detail(archive))).isInstanceOf(AccessDeniedException.class);as(actor,Set.of(UUID.randomUUID()),"finance.archive.read","finance.read");assertThatThrownBy(()->call(()->archives.detail(archive))).isInstanceOf(AccessDeniedException.class);}
 @Test void assetGainArchiveIndexesActualImmutableOriginalAndRechecksRealSourcePermissionBeforeDownload()throws Exception{UUID physical=UUID.randomUUID(),gain=UUID.randomUUID(),attachment=UUID.randomUUID();jdbc.update("insert into store_fixed_asset(id,tenant_id,hotel_org_unit_id,asset_code,name,category,original_value) values(?,?,?,?,?,'设备',0)",physical,T,hotel,physical.toString(),"盘盈实物");jdbc.update("insert into fs_asset_gain(id,tenant_id,hotel_id,company_id,book_id,physical_asset_id,department_id,financial_category_code,occurred_on,accounting_on,value,asset_account,credit_account,valuation_basis,policy_reference,applicant_id,reviewer_id,request_hash,physical_snapshot,category_snapshot) values(?,?,?,?,?,?,?,'REAL-ASSET','2026-10-20','2026-10-20',100,'1601','4001','真实独立估值依据','财务确认政策',?,?,?,'{}','{}')",gain,T,hotel,company,book,physical,hotel,actor,reviewer,"a".repeat(64));byte[] bytes="%PDF-1.4\nactual isolated valuation proof\n%%EOF".getBytes(StandardCharsets.UTF_8);String key=T+"/"+gain+"/"+UUID.randomUUID()+".original";Files.createDirectories(originals.resolve(key).getParent());Files.write(originals.resolve(key),bytes);jdbc.update("insert into fs_asset_gain_original(id,tenant_id,gain_id,original_name,media_type,size_bytes,sha256,object_key,scan_status,uploaded_by) values(?,?,?,'真实估值.pdf','application/pdf',?,?,?,'CLEAN',?)",attachment,T,gain,bytes.length,FinanceService.hash(bytes),key,actor);var gains=new FinanceAssetGainService(named,db,access,accounting,audit);var evidence=new FinanceAssetGainEvidenceService(originals.toString(),gains,access,new AttachmentMalwareScanner("","",1,false,false));var extended=extended(gains,evidence);var sources=new FinanceArchiveSources(named,access,null,null,accounting,null,insights,null);sources.setExtended(extended);var archives=new FinanceArchiveService(named,db,access,audit,sources);var preview=call(()->archives.preview("ASSET_GAIN",gain));var archived=call(()->archives.freeze(new FinanceArchiveModels.Freeze(UUID.randomUUID(),"ASSET_GAIN",gain,preview.get("sourceVersion").toString(),"盘盈原始估值",true)));UUID archive=id(archived.get("id"));assertThat(rows(map(archived.get("snapshot")).get("graph"))).anySatisfy(r->assertThat(r).containsEntry("type","ORIGINAL").containsEntry("sha256",FinanceService.hash(bytes)));var actual=call(()->extended.download("ASSET_GAIN",gain,attachment));assertThat(actual.resource().getContentAsByteArray()).isEqualTo(bytes);as(actor,Set.of(hotel),"finance.archive.grant");assertThatThrownBy(()->call(()->archives.recordOriginal(archive,attachment))).isInstanceOf(AccessDeniedException.class);as(actor,Set.of(hotel),"finance.read","finance.archive.read");Files.write(originals.resolve(key),"tampered".getBytes(StandardCharsets.UTF_8));assertThatThrownBy(()->call(()->extended.download("ASSET_GAIN",gain,attachment))).hasMessageContaining("原件缺失");}
