 private Set<UUID> queueIds(){return call(()->{var p=TenantContext.require();var b=new MapSqlParameterSource("tenantId",T).addValue("actorId",p.actorId()).addValue("tenantScope",p.hasTenantScope()).addValue("scopeIds",p.orgScopes()).addValue("review",p.hasPermission("finance.review")).addValue("payroll",p.hasPermission("finance.payroll")).addValue("tax",p.hasPermission("finance.tax")).addValue("own",p.hasPermission("finance.submit")).addValue("pay",p.hasPermission("finance.pay"));String first="select null::uuid id,''::text kind,''::text title,''::text hotel_name,''::text applicant_name,null::numeric amount,''::text status,null::date due_at,null::timestamptz waiting_since,false mismatch,0 version,''::text domain,''::text document_type where false";return new HashSet<>(named.query(first+FinancePendingV2.unionSql(named,p),b,(row,n)->row.getObject("id",UUID.class)));});}
 private String store(UUID source,byte[] bytes)throws Exception{String key=T+"/"+source+"/"+UUID.randomUUID()+".original";Files.createDirectories(originals.resolve(key).getParent());Files.write(originals.resolve(key),bytes);return key;}
 private UUID intake(byte[] bytes,String name)throws Exception{UUID id=UUID.randomUUID(),assignment=jdbc.queryForObject("select id from employee_position_assignment where tenant_id=? limit 1",UUID.class,T);String key=store(id,bytes);jdbc.update("insert into finance_invoice_intake(id,tenant_id,owner_id,assignment_id,hotel_id,original) values(?,?,?,?,?,?::jsonb)",id,T,actor,assignment,hotel,json(Map.of("originalName",name,"mediaType","application/pdf","sizeBytes",bytes.length,"sha256",FinanceService.hash(bytes),"objectKey",key,"scanStatus","CLEAN")));return id;}
 private FinanceArchiveExtendedSources extended(FinanceAssetGainService gains,FinanceAssetGainEvidenceService evidence){return new FinanceArchiveExtendedSources(named,db,access,audit,null,null,gains,evidence,accounting,null,null,null,null,null,null,null);}
 private Map<String,Object> closedReport(){var payload=new LinkedHashMap<String,Object>();payload.put("book",Map.of("id",book,"hotelId",hotel,"companyId",company));payload.put("month","2026-10");payload.put("status","FINAL");payload.put("reportVersion","closed-"+book);payload.put("completeness",Map.of("complete",true,"checks",List.of(Map.of("code","ACTUAL_CLOSED_SOURCE","passed",true,"meaning","隔离已关账真实三表来源的完整性结构"))));payload.put("incomeStatement",Map.of("revenue","100.00","expense","20.00","netProfit","80.00","lines",List.of()));payload.put("balanceSheet",Map.of("assets","100.00","liabilities","0.00","equity","20.00","unclosedProfit","80.00","difference","0.00","lines",List.of()));payload.put("cashFlowStatement",Map.of("beginningCash","0.00","endingCash","100.00","netMovement","100.00","categories",Map.of("OPERATING","100.00")));payload.put("detailLedger",List.of());payload.put("cashJournal",List.of());jdbc.update("insert into fa_period(tenant_id,book_id,month,status,close_snapshot,closed_by,closed_at) values(?,?,'2026-10-01','CLOSED',?::jsonb,?,now())",T,book,json(payload),actor);return call(()->accounting.reportSnapshot(book,"2026-10"));}
 private Map<String,Object> revenue(){UUID batch=UUID.randomUUID(),entry=UUID.randomUUID(),deposit=UUID.randomUUID();jdbc.update("insert into fb_revenue_batch(id,tenant_id,hotel_id,company_id,source,channel,business_date,night_audit_date,revision,expected_count,control_total,source_reference,status,source_hash,created_by,reviewer_id) values(?,?,?,?,'PMS','REAL-CHANNEL','2026-10-20','2026-10-21',1,2,130,'隔离测试真实来源','CONFIRMED',?,?,?)",batch,T,hotel,company,"a".repeat(64),actor,reviewer);for(var part:List.of(Map.of("id",entry,"kind","INCOME","amount","100.00"),Map.of("id",deposit,"kind","DEPOSIT","amount","30.00")))jdbc.update("insert into fb_revenue_entry(id,tenant_id,batch_id,hotel_id,company_id,external_id,kind,customer,channel,due_date,amount,net_amount,tax_amount,commission,fee,active) values(?,?,?,?,?,?,?,'客户私密','REAL-CHANNEL','2026-10-20',?::numeric,?::numeric,0,0,0,true)",part.get("id"),T,batch,hotel,company,part.get("id").toString(),part.get("kind"),part.get("amount"),part.get("amount"));UUID cash=movement(entry,"RECEIPT","2026-10-20","80.00",null),event=UUID.randomUUID();movement(deposit,"REDEEM","2026-10-21","5.00",entry);jdbc.update("insert into fa_source_event(id,tenant_id,hotel_id,company_id,source_type,source_id,event_key,business_date,accounting_date,amount,summary,metadata,request_hash,status) values(?,?,?,?,'FB_REVENUE_CASH',?,'RECEIPT','2026-10-20','2026-10-20',80,'原实际收款','{}',?,'PENDING_MAPPING')",event,T,hotel,company,cash,"b".repeat(64));jdbc.update("insert into fb_cash_correction(id,tenant_id,source_type,source_id,hotel_id,company_id,original_kind,original_source_event_id,amount,business_date,accounting_on,note,proof,created_by) values(?,?,'REVENUE',?,?,?,'RECEIPT',?,10,'2026-10-20','2026-10-21','真实差错独立更正','{}',?)",UUID.randomUUID(),T,cash,hotel,company,event,actor);return Map.of("entry",entry,"batch",batch);}
 private UUID movement(UUID entry,String kind,String day,String amount,UUID related){UUID id=UUID.randomUUID();jdbc.update("insert into fb_revenue_movement(id,tenant_id,entry_id,kind,amount,occurred_on,bank_reference,note,related_entry_id,created_by) values(?,?,?,?,?::numeric,?::date,?,'隔离验收真实资金依据',?,?)",id,T,entry,kind,amount,day,id.toString(),related,actor);return id;}
 private UUID account(){UUID id=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'日报档案验收')",id,T,id.toString());return id;}
 private UUID hotel(){UUID id=UUID.randomUUID();jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'日报验收店','HOTEL')",id,T,id.toString());return id;}
 private void as(UUID account,Set<UUID> scopes,String...permissions){TenantContext.set(new TenantPrincipal(T,account,"TEST",Set.of("TEST"),Set.of(permissions),scopes,Set.of(),false,UUID.randomUUID()));}
 private static <R>R call(Supplier<R> action){return tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");jdbc.queryForObject("select set_config('app.tenant_id',?,true)",String.class,T.toString());return action.get();});}
